pub fn check_if_last_char_is_a_letter(txt: &str) -> bool {
    // Work in Unicode scalar values (chars), not bytes.
    let mut it = txt.chars().rev();

    // Must be non-empty.
    let last = match it.next() {
        Some(c) => c,
        None => return false,
    };

    // Last character must be an ASCII alphabetic letter.
    if !last.is_ascii_alphabetic() {
        return false;
    }

    // If there's no previous character, it's a 1-char string => ok.
    match it.next() {
        None => true,
        Some(prev) => prev == ' ',
    }
}